css:
.wrapper {
  --anim: 3.5s;
  position: relative;
  display: flex;
  place-items: center;
}

.txt-wrapper {
  position: relative;
  display: flex;
  z-index: 1;
  animation: scale-txt var(--anim) ease-in-out infinite;
}

.wrapper .txt-wrapper .txt {
  user-select: none;
  text-transform: uppercase;
  z-index: 1;
  justify-self: center;
  font-family: "Inter", sans-serif;
  font-weight: 700;
  font-size: 1.15rem;
  color: #0005;
  animation: letter calc(var(--anim) * 0.75) ease-in infinite;
  animation-delay: calc(var(--i) * 0.095s);
}

.wrapper .layer {
  --h: 48px;
  --x-pad: 32px;
  --deg-rot: 1.4deg;

  position: absolute;
  z-index: 0;
  inset: calc(1.15rem - 0.66 * var(--h)) calc(-1 * var(--x-pad));
  border-radius: var(--h) / calc(2.2 * var(--h));
  border: dashed 3.5px #000c;
  background-color: hsl(calc(var(--i) * 30deg), 75%, 50%);
  transform: rotate(calc(var(--i) * var(--deg-rot)));
  animation: rotate var(--anim) ease-in-out infinite;
  mix-blend-mode: screen;
  filter: blur(1px);
}

@keyframes rotate {
  50% {
    transform: rotate(calc(var(--i) * -1 * var(--deg-rot)));
  }
}
@keyframes letter {
  35% {
    filter: blur(2px);
  }
}
@keyframes scale-txt {
  50% {
    transform: scale(1.1);
  }
}
